import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.GeneratedValue;

@Entity
class Category extends BaseEntity<Long> {
    @Id
    @GeneratedValue
    private Long id;
    private String name;
    private String slug;

    @Override
    public Long getId() {
        return id;
    }
}

import jakarta.persistence.CascadeType;
import jakarta.persistence.Entity;
import jakarta.persistence.OneToOne;

@Entity
class User extends BaseEntity<Long> {
    private String email;
    private String passwordHash;
    private String role;

    // Xoa/luu User se tu dong lan truyen sang UserProfile lien ket.
    @OneToOne(cascade = CascadeType.ALL, orphanRemoval = true)
    private UserProfile profile;
}

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.web.SecurityFilterChain;

@Configuration
class SecurityConfig {

    @Bean
    SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http.authorizeHttpRequests(auth -> auth
                .requestMatchers("/api/auth/**").permitAll()
                .anyRequest().authenticated())
            // Resource Server: xac thuc JWT dua tren issuer-uri, khong tu quan ly session.
            .oauth2ResourceServer(oauth2 -> oauth2.jwt(jwt -> {}));
        return http.build();
    }
}
